**Use Case:** When you prefer InstructPix2Pix for consistent results

### Example 5: Comprehensive Error Handling

**Request:**
```typescript
async function editImageWithRetry(image, prompt, maxRetries = 2) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      const response = await fetch('/api/ai/image/edit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ image, prompt })
      });

      // Handle rate limiting
      if (response.status === 429) {
        const retryAfter = parseInt(response.headers.get('Retry-After') || '60');
        console.log(`Rate limited. Waiting ${retryAfter}s...`);
        await new Promise(r => setTimeout(r, retryAfter * 1000));
        continue;
      }

      // Handle other errors
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error);
      }

      const data = await response.json();

      // Download and save (URLs expire after 24h)
      const imageBlob = await fetch(data.url).then(r => r.blob());
      const permanentUrl = await uploadToStorage(imageBlob);

      return permanentUrl;
    } catch (error) {
      console.error(`Attempt ${attempt + 1} failed:`, error.message);
      if (attempt === maxRetries - 1) throw error;

      // Exponential backoff
      await new Promise(r => setTimeout(r, Math.pow(2, attempt) * 1000));
    }
  }
}

// Usage
try {
  const editedUrl = await editImageWithRetry(
    'https://example.com/image.png',
    'Add vibrant sunset colors'
  );
  console.log('Successfully edited:', editedUrl);
} catch (error) {
  console.error('All retries exhausted:', error.message);
}
```

